insert into regions (slug, country_id, name_en, name_it, verification_status, last_verified_at, source_url, publication_status, is_demo) select 'dubai-emirate', id, 'Dubai Emirate', 'Emirato di Dubai', 'verified', '2026-10-01', null, 'published', true from countries where slug = 'united-arab-emirates' on conflict do nothing;
insert into cities (slug, country_id, region_id, name_en, name_it, lat, lng, intro_en, intro_it, best_time_en, best_time_it, verification_status, last_verified_at, source_url, publication_status, is_demo) select 'paris', co.id, (select id from regions where slug = 'ile-de-france'), 'Paris', 'Parigi', 48.8566, 2.3522, 'Paris remains a reference point for formal dining, from classical brigades and silver-domed service to small counters run by a single chef. Tasting menus dominate in the evening, while many dining rooms offer a shorter, better-value lunch on weekdays. Neighbourhood matters: the Left Bank leans traditional, the eastern arrondissements more experimental. Expect dress codes to be relaxed but service to be precise, and book well ahead for weekend evenings and for counter seats.', 'Parigi resta un punto di riferimento per l''alta ristorazione, dalle brigate classiche con servizio a cloche ai piccoli banconi guidati da un solo chef. La sera dominano i menu degustazione, mentre molte sale propongono a pranzo, nei giorni feriali, un menu più breve e conveniente. Il quartiere conta: la Rive Gauche è più tradizionale, gli arrondissement orientali più sperimentali. Il dress code è rilassato ma il servizio preciso: prenotate con anticipo per i fine settimana e per i posti al bancone.', 'Four to six weeks ahead for dinner; weekday lunch often within a week.', 'Da quattro a sei settimane prima per la cena; il pranzo feriale spesso entro una settimana.', 'verified', '2026-10-01', null, 'published', true from countries co where co.slug = 'france' on conflict do nothing;
insert into cities (slug, country_id, region_id, name_en, name_it, lat, lng, intro_en, intro_it, best_time_en, best_time_it, verification_status, last_verified_at, source_url, publication_status, is_demo) select 'tokyo', co.id, (select id from regions where slug = 'kanto'), 'Tokyo', null, 35.6762, 139.6503, 'Tokyo''s fine dining is defined by specialisation: counters devoted to sushi, tempura, kaiseki or grilled skewers, often seating fewer than twelve guests. Many restaurants work with fixed seatings and set start times, so punctuality is part of the experience. Seasonal ingredients drive menus that can change weekly. Reservations are frequently released one to two months ahead and some venues accept bookings only through a hotel concierge or a local reservation platform.', 'L''alta cucina di Tokyo è definita dalla specializzazione: banconi dedicati a sushi, tempura, kaiseki o spiedini alla griglia, spesso con meno di dodici coperti. Molti ristoranti lavorano con turni fissi e orari d''inizio precisi, quindi la puntualità fa parte dell''esperienza. Gli ingredienti di stagione guidano menu che possono cambiare ogni settimana. Le prenotazioni si aprono spesso con uno o due mesi di anticipo e alcuni locali accettano richieste solo tramite il concierge dell''hotel o piattaforme locali.', 'As soon as the booking window opens, typically 30–60 days ahead.', 'Appena si apre la finestra di prenotazione, di solito 30–60 giorni prima.', 'verified', '2026-10-01', null, 'published', true from countries co where co.slug = 'japan' on conflict do nothing;
insert into cities (slug, country_id, region_id, name_en, name_it, lat, lng, intro_en, intro_it, best_time_en, best_time_it, verification_status, last_verified_at, source_url, publication_status, is_demo) select 'milan', co.id, (select id from regions where slug = 'lombardy'), 'Milan', 'Milano', 45.4642, 9.19, 'Milan combines a strong Lombard tradition — saffron risotto, slow-cooked veal, lake fish — with some of Italy''s most design-led dining rooms. Business lunches keep many kitchens busy at midday, which makes lunch menus a practical way to try ambitious cooking. Restaurants cluster around Brera, the Navigli canals and the newer Porta Nuova district. Many close in August and around Christmas, so check opening periods before planning a trip.', 'Milano unisce una forte tradizione lombarda — risotto allo zafferano, ossobuco, pesce di lago — ad alcune delle sale più attente al design in Italia. I pranzi di lavoro tengono attive molte cucine a mezzogiorno, e i menu del pranzo sono un modo pratico per provare cucine ambiziose. I ristoranti si concentrano tra Brera, i Navigli e il quartiere di Porta Nuova. Molti chiudono ad agosto e nel periodo natalizio: verificate le aperture prima di organizzare il viaggio.', 'Two to three weeks ahead; longer during Design Week and Fashion Week.', 'Due o tre settimane prima; di più durante la Design Week e la Fashion Week.', 'verified', '2026-10-01', null, 'published', true from countries co where co.slug = 'italy' on conflict do nothing;
insert into cities (slug, country_id, region_id, name_en, name_it, lat, lng, intro_en, intro_it, best_time_en, best_time_it, verification_status, last_verified_at, source_url, publication_status, is_demo) select 'london', co.id, (select id from regions where slug = 'england'), 'London', 'Londra', 51.5072, -0.1276, 'London''s top tables range from grand hotel dining rooms in Mayfair to compact, produce-led kitchens in the east of the city. Modern British cooking sits alongside strong Indian, Japanese and Mediterranean traditions. Service charges of around 12.5% are commonly added to the bill, so compare prices with that in mind. Lunch and early-evening menus are widely offered and are often the most accessible way into the city''s most sought-after rooms.', 'I migliori tavoli di Londra spaziano dalle sale degli storici hotel di Mayfair a cucine compatte e incentrate sul prodotto nella zona est. La cucina britannica moderna convive con forti tradizioni indiane, giapponesi e mediterranee. Al conto viene spesso aggiunto un servizio di circa il 12,5%: tenetene conto nel confronto dei prezzi. Pranzo e menu del primo turno serale sono molto diffusi e spesso sono il modo più accessibile per entrare nelle sale più richieste.', 'Three to four weeks ahead; many releases happen at a fixed time each month.', 'Tre o quattro settimane prima; molte disponibilità si aprono a orari fissi ogni mese.', 'verified', '2026-10-01', null, 'published', true from countries co where co.slug = 'united-kingdom' on conflict do nothing;
insert into cities (slug, country_id, region_id, name_en, name_it, lat, lng, intro_en, intro_it, best_time_en, best_time_it, verification_status, last_verified_at, source_url, publication_status, is_demo) select 'new-york', co.id, (select id from regions where slug = 'new-york-state'), 'New York', null, 40.7128, -74.006, 'New York''s fine dining moves quickly: chef''s counters, seafood-focused tasting menus and reinvented classics open across Manhattan and Brooklyn every season. Prices are typically quoted before tax and tip, so the final bill can be considerably higher than the menu price. Many restaurants release tables on a rolling 28- or 30-day window, and walk-in bar seating is common. Dress codes are relaxed, though jackets remain welcome in older dining rooms.', 'L''alta ristorazione di New York si muove in fretta: banconi dello chef, degustazioni di mare e classici reinventati aprono ogni stagione tra Manhattan e Brooklyn. I prezzi sono di norma indicati al netto di tasse e mancia, quindi il conto finale può essere molto più alto del prezzo del menu. Molti ristoranti aprono le prenotazioni con una finestra mobile di 28 o 30 giorni e i posti al bar senza prenotazione sono comuni. Il dress code è rilassato, ma la giacca resta gradita nelle sale più classiche.', 'Exactly when the rolling window opens, usually 28–30 days ahead.', 'Proprio quando si apre la finestra mobile, di solito 28–30 giorni prima.', 'verified', '2026-10-01', null, 'published', true from countries co where co.slug = 'united-states' on conflict do nothing;
insert into cities (slug, country_id, region_id, name_en, name_it, lat, lng, intro_en, intro_it, best_time_en, best_time_it, verification_status, last_verified_at, source_url, publication_status, is_demo) select 'dubai', co.id, (select id from regions where slug = 'dubai-emirate'), 'Dubai', null, 25.2048, 55.2708, 'Dubai''s dining scene is concentrated in hotels and waterfront districts, with international chefs working alongside a growing number of local and regional concepts. Menus draw on Levantine, Persian, Indian and Japanese influences. The cooler months from November to March are the busiest, and outdoor terraces are most enjoyable then. Many venues set minimum ages or dress codes for evening service, so read the reservation notes carefully.', 'La scena gastronomica di Dubai si concentra negli hotel e nei quartieri sul mare, con chef internazionali affiancati da un numero crescente di progetti locali e regionali. I menu attingono a influenze levantine, persiane, indiane e giapponesi. I mesi più freschi, da novembre a marzo, sono i più affollati e le terrazze all''aperto danno il meglio. Molti locali prevedono età minime o dress code per la sera: leggete con attenzione le note di prenotazione.', 'Two weeks ahead in peak season (November–March).', 'Due settimane prima in alta stagione (novembre–marzo).', 'verified', '2026-10-01', null, 'published', true from countries co where co.slug = 'united-arab-emirates' on conflict do nothing;
insert into cities (slug, country_id, region_id, name_en, name_it, lat, lng, intro_en, intro_it, best_time_en, best_time_it, verification_status, last_verified_at, source_url, publication_status, is_demo) select 'rome', co.id, (select id from regions where slug = 'lazio'), 'Rome', 'Roma', 41.9028, 12.4964, 'Rome''s ambitious kitchens often reinterpret the city''s own canon — carbonara, cacio e pepe, offal and artichokes — with lighter technique and long-matured ingredients. Rooftop dining rooms with views over the historic centre are a speciality, alongside quieter restaurants in Prati and Monti. Dinner starts late by northern European standards. Summer evenings fill up quickly, and many restaurants close for part of August.', 'Le cucine più ambiziose di Roma reinterpretano spesso il canone cittadino — carbonara, cacio e pepe, quinto quarto e carciofi — con tecniche più leggere e ingredienti a lunga maturazione. Le sale panoramiche sui tetti del centro storico sono una specialità, accanto a ristoranti più raccolti a Prati e Monti. Si cena tardi rispetto agli standard nordeuropei. Le sere d''estate si riempiono in fretta e molti ristoranti chiudono per parte di agosto.', 'Two to four weeks ahead; terraces book out first in summer.', 'Da due a quattro settimane prima; d''estate le terrazze finiscono per prime.', 'verified', '2026-10-01', null, 'published', true from countries co where co.slug = 'italy' on conflict do nothing;
insert into cities (slug, country_id, region_id, name_en, name_it, lat, lng, intro_en, intro_it, best_time_en, best_time_it, verification_status, last_verified_at, source_url, publication_status, is_demo) select 'barcelona', co.id, (select id from regions where slug = 'catalonia'), 'Barcelona', 'Barcellona', 41.3874, 2.1686, 'Barcelona pairs a deep Catalan pantry — seafood, rice, preserved vegetables and cured meats — with a long history of technical experimentation. Long tasting menus coexist with lively counter dining where small plates arrive one by one. Lunch is the main meal for many locals and often starts after 2 pm, while dinner rarely begins before 8.30 pm. Natural and Catalan wines feature prominently on pairings.', 'Barcellona unisce una ricca dispensa catalana — pesce, riso, verdure conservate e salumi — a una lunga storia di sperimentazione tecnica. I lunghi menu degustazione convivono con vivaci banconi dove i piccoli piatti arrivano uno alla volta. Per molti abitanti il pranzo è il pasto principale e inizia spesso dopo le 14, mentre la cena raramente prima delle 20.30. Vini naturali e catalani hanno un ruolo di primo piano negli abbinamenti.', 'Three weeks ahead; avoid the second half of August when many close.', 'Tre settimane prima; evitate la seconda metà di agosto, quando molti chiudono.', 'verified', '2026-10-01', null, 'published', true from countries co where co.slug = 'spain' on conflict do nothing;
insert into cities (slug, country_id, region_id, name_en, name_it, lat, lng, intro_en, intro_it, best_time_en, best_time_it, verification_status, last_verified_at, source_url, publication_status, is_demo) select 'copenhagen', co.id, (select id from regions where slug = 'capital-region'), 'Copenhagen', 'Copenaghen', 55.6761, 12.5683, 'Copenhagen''s restaurants are known for close relationships with farmers, foragers and fishers, and for menus that follow the short Nordic growing season closely. Fermentation, preserving and open-fire cooking are common threads. Many restaurants run seasonal menus that change entirely several times a year, and some close between seasons. Bookings often open months in advance for the best-known rooms, while wine bars offer a more spontaneous alternative.', 'I ristoranti di Copenaghen sono noti per il rapporto stretto con agricoltori, raccoglitori e pescatori, e per menu che seguono da vicino la breve stagione nordica. Fermentazione, conserve e cottura sul fuoco vivo sono fili conduttori comuni. Molti propongono menu stagionali che cambiano completamente più volte l''anno, e alcuni chiudono tra una stagione e l''altra. Per le sale più note le prenotazioni si aprono con mesi di anticipo, mentre i wine bar offrono un''alternativa più spontanea.', 'Two to three months ahead for the best-known rooms.', 'Due o tre mesi prima per le sale più note.', 'verified', '2026-10-01', null, 'published', true from countries co where co.slug = 'denmark' on conflict do nothing;
insert into cities (slug, country_id, region_id, name_en, name_it, lat, lng, intro_en, intro_it, best_time_en, best_time_it, verification_status, last_verified_at, source_url, publication_status, is_demo) select 'singapore', co.id, (select id from regions where slug = ''), 'Singapore', null, 1.3521, 103.8198, 'Singapore''s fine dining reflects its position as a crossroads: modern Cantonese, Peranakan, Japanese and contemporary European kitchens operate within a few blocks of each other. Many restaurants sit in hotels or restored shophouses around the Central Business District and Tanjong Pagar. Prices are generally quoted before a 10% service charge and goods and services tax. Lunch menus are widely available and good value relative to dinner.', 'L''alta cucina di Singapore riflette il suo ruolo di crocevia: cucine cantonesi moderne, peranakan, giapponesi ed europee contemporanee convivono a pochi isolati di distanza. Molti ristoranti si trovano in hotel o in shophouse restaurate tra il Central Business District e Tanjong Pagar. I prezzi sono in genere indicati al netto del 10% di servizio e dell''imposta sui beni e servizi. I menu del pranzo sono molto diffusi e convenienti rispetto alla cena.', 'Two to three weeks ahead; longer around public holidays.', 'Due o tre settimane prima; di più in prossimità delle festività.', 'verified', '2026-10-01', null, 'published', true from countries co where co.slug = 'singapore' on conflict do nothing;
