insert into chefs (slug, name, bio_en, verification_status, last_verified_at, source_url, publication_status, is_demo) values ('luca-ferraris', 'Luca Ferraris', 'Reinterprets Lombard classics with a lighter hand; his saffron risotto is finished tableside.', 'verified', '2026-10-01', null, 'published', true) on conflict do nothing;
