insert into chefs (slug, name, bio_en, verification_status, last_verified_at, source_url, publication_status, is_demo) values ('marco-dellarosa', 'Marco Della Rosa', 'Roman by birth, he rebuilt his grandmother''s offal recipes into a refined tasting menu.', 'verified', '2026-10-01', null, 'published', true) on conflict do nothing;
